#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long h;
    long long w;
    cin >> h >> w;
    vector<string> grid(h);
    for (int i = 0; i < h; i++) {
        cin >> grid[i];
    }

    vector<string> cells = grid;
    vector<pair<int, int>> layer;
    long long fresh = 0;
    for (int x = 0; x < h; x++) {
        for (int y = 0; y < w; y++) {
            if (cells[x][y] == '2') layer.push_back({x, y});
            else if (cells[x][y] == '1') fresh++;
        }
    }
    int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};
    long long minutes = 0;
    while (!layer.empty() && fresh > 0) {
        vector<pair<int, int>> next;
        for (const auto& cell : layer) {
            for (int d = 0; d < 4; d++) {
                int a = cell.first + dx[d], b = cell.second + dy[d];
                if (a >= 0 && a < h && b >= 0 && b < w && cells[a][b] == '1') {
                    cells[a][b] = '2';
                    fresh--;
                    next.push_back({a, b});
                }
            }
        }
        layer = next;
        minutes++;
    }
    cout << (fresh == 0 ? minutes : -1) << "\n";

    return 0;
}

